// Receipts generated by test_m6_reference_acceptance against an isolated DB.
// Run it with M6_ACCEPTANCE_RECEIPTS=<repo>/.artifacts/batch304/m6-receipts.
// No hand-authored success response and no connection to business APIs.
import {createApp, h, ref, computed} from 'vue'
import {api} from '../../src/services/api'
import ExecutionPromptDisplay from '../../src/components/ExecutionPromptDisplay.vue'
import ExecutionStorageMetrics from '../../src/components/ExecutionStorageMetrics.vue'
import FrozenReferenceCorrespondence from '../../src/components/FrozenReferenceCorrespondence.vue'
import {adaptFrozenReferenceBinding} from '../../src/services/frozenReferenceBinding'
import names from '../../../.artifacts/batch304/m6-receipts/names.json'
import variants from '../../../.artifacts/batch304/m6-receipts/variants.json'
import '../../src/styles.css'
import '../../src/platform.css'

const scenario = ref('variants'), order = ref(0), failed = ref(false), readCount = ref(0)
const receipt = computed(() => (scenario.value === 'variants' ? variants : names)[order.value]!)
const adapter = async (config: any) => {
  const current = receipt.value
  if (config.method !== 'get' || config.data !== undefined
    || Object.keys(config.params || {}).join() !== 'expected_preparation_revision'
    || config.params.expected_preparation_revision !== current.preparation.revision) throw Error('隔离夹具禁止实际请求或错误修订')
  const base = `/execution-preparations/${current.preparation.id}/`
  const data = config.url === base + 'prompt-display/' ? current.prompt
    : config.url === base + 'storage-metrics/' ? current.metrics : null
  if (!data) throw Error('隔离夹具禁止未声明API')
  readCount.value++
  if (failed.value) throw Error('隔离错误：原准备读取失败')
  return {config, data: structuredClone(data), status: 200, statusText: 'OK', headers: {}}
}
api.defaults.adapter = adapter
api.interceptors.request.use(config => {config.adapter = adapter; config.headers.delete('Authorization'); return config})
createApp({setup: () => () => h('main', {style: {maxWidth: '1000px', minWidth: 0, margin: '16px auto', padding: '16px'}}, [
  h('h1', '隔离：M6 原名与双变体组合'),
  h('p', '正式组件读取隔离后端测试的真实API回执；不是现用业务、模型结果或真实调用验收。所有业务请求已阻断。'),
  h('div', {style: {display: 'flex', gap: '12px', flexWrap: 'wrap'}}, [
    h('label', ['组合 ', h('select', {value: scenario.value, onChange: (event: Event) => {scenario.value = (event.target as HTMLSelectElement).value}}, [
      h('option', {value: 'variants'}, '同一实体：校服与外套'), h('option', {value: 'names'}, '多语言同名：Ｃafé / Café'),
    ])]),
    h('button', {class: 'button', onClick: () => {order.value = 1 - order.value}}, order.value ? '查看原顺序' : '查看重排后准备'),
    h('button', {class: 'button', onClick: () => {failed.value = !failed.value}}, failed.value ? '恢复读取' : '模拟读取失败'),
  ]),
  h('p', {role: 'status'}, `已记录${order.value ? '重排' : '原顺序'}准备 · 隔离读取 ${readCount.value} 次 · 真实请求 0`),
  h('section', {style: {display: 'grid', gap: '16px'}}, Object.entries(receipt.value.correspondence).map(([key, value]) => {
    const media = receipt.value.media.find(row => row.item_key === key)!
    return h('article', {key: receipt.value.preparation.id + key}, [
      h('p', `${media.label} · 隔离PNG原字节预览（不是人物生成结果）`),
      h('img', {src: media.data_url, alt: `${media.label} 隔离参考图`, style: {width: '72px', height: '72px', objectFit: 'contain'}}),
      h(FrozenReferenceCorrespondence, {binding: adaptFrozenReferenceBinding(value)}),
    ])
  })),
  h(ExecutionPromptDisplay, {preparationId: receipt.value.preparation.id, revision: receipt.value.preparation.revision,
    frozen: false, disabled: false, fieldLabels: {configured_action: '动作'} }),
  h(ExecutionStorageMetrics, {preparationId: receipt.value.preparation.id, revision: receipt.value.preparation.revision, disabled: false}),
])}).mount('#app')
